#[allow(dead_code)]
#[path = "src/ipc_commands.rs"]
mod ipc_commands;

fn main() {
    println!("cargo:rerun-if-changed=src/ipc_commands.rs");
    if std::env::var_os("CARGO_FEATURE_DESKTOP").is_some() {
        // Keep our central permission in build output. AppManifest::commands also
        // emits Tauri's per-command templates under permissions/autogenerated.
        let permission_path = std::path::PathBuf::from(std::env::var_os("OUT_DIR").unwrap())
            .join("main-window-commands.json");
        std::fs::write(&permission_path, ipc_commands::permission_definition())
            .expect("write application IPC permission");
        let permission_pattern = Box::leak(
            permission_path
                .to_str()
                .expect("UTF-8 application permission path")
                .to_owned()
                .into_boxed_str(),
        );
        tauri_build::try_build(
            tauri_build::Attributes::new().app_manifest(
                tauri_build::AppManifest::new()
                    .commands(ipc_commands::COMMANDS)
                    .permissions_path_pattern(permission_pattern),
            ),
        )
        .expect("build Tauri application ACL");
    }
}
